mapper.update:
UPDATE tb_admin_resource
SET status = #{status},
    payload_json = #{payloadJson},
    active_flag = #{activeFlag},
    last_rotated_at = #{lastRotatedAt},
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND resource_type = #{resourceType}
  AND resource_key = #{resourceKey}

UPDATE tb_admin_resource
SET active_flag = FALSE,
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND resource_type = #{resourceType}
  AND active_flag = TRUE

mapper.select:
SELECT id,
       trace_id,
       event_type,
       metric_key,
       metric_value,
       CAST(dimensions_json AS VARCHAR) AS dimensions_json,
       event_time
FROM tb_ops_event
WHERE tenant_id = #{tenantId}

      AND event_time >= #{fromUtc}


      AND event_time <= #{toUtc}


      AND (
          LOWER(metric_key) LIKE CONCAT('%', LOWER(#{keyword}), '%')
          OR LOWER(event_type) LIKE CONCAT('%', LOWER(#{keyword}), '%')
          OR LOWER(CAST(trace_id AS VARCHAR)) LIKE CONCAT('%', LOWER(#{keyword}), '%')
          OR LOWER(CAST(dimensions_json AS VARCHAR)) LIKE CONCAT('%', LOWER(#{keyword}), '%')
      )

ORDER BY event_time DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT metric_key,
       SUM(metric_value) AS metric_value
FROM tb_api_metric_hourly
WHERE tenant_id = #{tenantId}

      AND hour_bucket_utc >= #{fromUtc}


      AND hour_bucket_utc <= #{toUtc}

GROUP BY metric_key
ORDER BY metric_key ASC
